#include <stdio.h>

int main(void) {
    puts("C language mode report");
#if !defined(__STDC_VERSION__)
    puts("__STDC_VERSION__ is not defined in this mode");
#elif __STDC_VERSION__ >= 202311L
    puts("C23 version macro or later");
#elif __STDC_VERSION__ >= 201710L
    puts("C17/C18 version macro");
#elif __STDC_VERSION__ >= 201112L
    puts("C11 version macro");
#elif __STDC_VERSION__ >= 199901L
    puts("C99 version macro");
#elif __STDC_VERSION__ >= 199409L
    puts("C95 amendment-era version macro");
#else
    puts("Earlier or implementation-specific language mode");
#endif
#ifdef __STDC__
    printf("__STDC__=%d\n", __STDC__);
#else
    puts("__STDC__ is not defined");
#endif
    return 0;
}

#include <stdio.h>

#if !defined(__STDC_VERSION__) || __STDC_VERSION__ < 201112L
#error "This project requires C11 or a later standard mode"
#endif

_Static_assert(sizeof(int) >= 2,
               "The implementation must provide at least 2 bytes per int");

int main(void) {
    printf("C11-or-later target accepted; sizeof(int)=%zu\n",
           sizeof(int));
    return 0;
}
